#!/bin/bash
set -euo pipefail

# Content Moderation Pipeline - Production Safety - Generated by flowsh
# Registry-based workflow execution script

echo "Starting workflow: Content Moderation Pipeline - Production Safety"

# Workflow variables and state management
declare -A workflow_vars
declare -A workflow_state

# Color codes for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
NC='\033[0m'

# Configuration
VERBOSE=${VERBOSE:-false}
AGENT_TIMEOUT=${AGENT_TIMEOUT:-60}

# =============================================================================
# VARIABLE MANAGEMENT FUNCTIONS
# =============================================================================

# Set variable with debug logging
# Usage: set_var "variable_name" "value" "node_id"
set_var() {
    local var_name="$1"
    local value="$2" 
    local node_id="${3:-root}"
    
    # Set the variable globally
    declare -g "$var_name"="$value"
    
    # Debug logging when FLOWSH_DEBUG=true
    if [[ "${FLOWSH_DEBUG:-false}" == "true" ]]; then
        echo "[DEBUG] $node_id: SET $var_name = '$value'" >&2
    fi
}

# Get variable value with debug logging  
# Usage: get_var "variable_name" "node_id"
get_var() {
    local var_name="$1"
    local node_id="${2:-root}"
    
    # Get the variable value using indirect expansion
    local value="${!var_name:-}"
    
    # Debug logging when FLOWSH_DEBUG=true
    if [[ "${FLOWSH_DEBUG:-false}" == "true" ]]; then
        echo "[DEBUG] $node_id: GET $var_name = '$value'" >&2
    fi
    
    # Return the value
    echo "$value"
}

# Environment Variables
LLM_CONTENT=${LLM_CONTENT:-""}
LLM_SUCCESS=${LLM_SUCCESS:-""}
MODERATION_SUMMARY=${MODERATION_SUMMARY:-""}

# =============================================================================
# UTILITY FUNCTIONS
# =============================================================================

# Logging functions with colors
log_info() {
    echo -e "${CYAN}ℹ️  $*${NC}"
}

log_success() {
    echo -e "${GREEN}✅ $*${NC}"
}

log_error() {
    echo -e "${RED}❌ $*${NC}" >&2
}

log_warning() {
    echo -e "${YELLOW}⚠️  $*${NC}" >&2
}

log_debug() {
    [[ "$VERBOSE" == "true" ]] && echo -e "${BLUE}🔍 DEBUG: $*${NC}" >&2 || true
}

log_step() {
    echo -e "${CYAN}🚀 $*${NC}"
}

# Operation logging with correlation IDs
log_operation_start() {
    local operation_name="$1"
    local operation_type="$2"
    local correlation_id="$3"
    log_debug "$correlation_id" "Starting $operation_type: $operation_name"
}

log_operation_end() {
    local operation_name="$1"
    local operation_type="$2"
    local correlation_id="$3"
    local status="${4:-success}"
    log_debug "$correlation_id" "Completed $operation_type: $operation_name ($status)"
}

# Enhanced error handling
handle_error() {
    local exit_code=$1
    local context="$2"
    local node_id="${3:-unknown}"
    
    case $exit_code in
        124)
            log_error "Timeout: $context took longer than ${AGENT_TIMEOUT}s (node: $node_id)"
            ;;
        127)
            log_error "Command not found in: $context (node: $node_id)"
            ;;
        1)
            log_error "General error in: $context (node: $node_id)"
            ;;
        *)
            log_error "Unknown error (exit code $exit_code) in: $context (node: $node_id)"
            ;;
    esac
    
    return $exit_code
}

# Variable management
set_workflow_var() {
    local var_name="$1"
    local var_value="$2"
    workflow_vars["$var_name"]="$var_value"
    log_debug "Set variable: $var_name = $var_value"
}

get_workflow_var() {
    local var_name="$1"
    local default_value="${2:-}"
    
    # First check workflow_vars array
    local workflow_value="${workflow_vars[$var_name]:-}"
    if [[ -n "$workflow_value" ]]; then
        echo "$workflow_value"
        return
    fi
    
    # Fallback to environment variable (uppercase version)
    local env_var_name="${var_name^^}"  # Convert to uppercase
    local env_value="${!env_var_name:-}"
    if [[ -n "$env_value" ]]; then
        echo "$env_value"
        return
    fi
    
    # Finally use default value
    echo "$default_value"
}

# State management
set_workflow_state() {
    local state_key="$1"
    local state_value="$2"
    workflow_state["$state_key"]="$state_value"
    log_debug "Set state: $state_key = $state_value"
}

get_workflow_state() {
    local state_key="$1"
    local default_value="${2:-}"
    echo "${workflow_state[$state_key]:-$default_value}"
}

# Temporary file management
declare -a FLOWSH_TEMP_FILES=()

register_temp_file() {
    local temp_path="$1"
    FLOWSH_TEMP_FILES+=("$temp_path")
    log_debug "Registered temp file: $temp_path"
}

cleanup_temp_files() {
    local cleaned_count=0
    local failed_count=0
    
    for temp_file in "${FLOWSH_TEMP_FILES[@]}"; do
        if [[ -e "$temp_file" ]]; then
            if rm -rf "$temp_file" 2>/dev/null; then
                ((cleaned_count++))
                log_debug "Cleaned up temp file: $temp_file"
            else
                ((failed_count++))
                log_warning "Failed to clean up temp file: $temp_file"
            fi
        fi
    done
    
    # Clear the temp files array
    FLOWSH_TEMP_FILES=()
    
    if [[ $cleaned_count -gt 0 ]]; then
        log_info "Cleaned up $cleaned_count temporary files"
    fi
    
    if [[ $failed_count -gt 0 ]]; then
        log_warning "Failed to clean up $failed_count temporary files"
    fi
    
    return 0
}

# Variable substitution in templates
substitute_variables() {
    local template="$1"
    local result="$template"
    
    # Find all variable references in the format {{#variable_name#}}
    while [[ $result =~ \{\{#([^#]+)#\}\} ]]; do
        local var_ref="${BASH_REMATCH[1]}"
        local var_value=$(get_workflow_var "$var_ref" "")
        
        if [[ -z "$var_value" ]]; then
            log_warning "Variable reference '$var_ref' not found, using empty string"
        fi
        
        # Escape special characters for sed
        local escaped_value=$(printf '%s\n' "$var_value" | sed 's/[[\.\*^\$()+?{|]/\\&/g')
        result=$(echo "$result" | sed "s|{{#${var_ref}#}}|$escaped_value|g")
    done
    
    echo "$result"
}

# Process tracking for parallel execution
declare -a FLOWSH_ACTIVE_PIDS=()

register_process() {
    local pid="$1"
    local description="${2:-unknown}"
     
     # Use case statement instead of regex for PID validation
     case "$pid" in
         ''|*[!0-9]*) log_warning "Invalid PID for registration: $pid" ;;
         *)
             FLOWSH_ACTIVE_PIDS+=("$pid")
             log_debug "Registered process $pid: $description"
             ;;
     esac
}

unregister_process() {
    local pid="$1"
    local new_pids=()
    
    for active_pid in "${FLOWSH_ACTIVE_PIDS[@]}"; do
        if [[ "$active_pid" != "$pid" ]]; then
            new_pids+=("$active_pid")
        fi
    done
    
    FLOWSH_ACTIVE_PIDS=("${new_pids[@]}")
    log_debug "Unregistered process $pid"
}

# Mock circuit breaker operation for testing
execute_circuit_breaker_operation() {
    local timeout_seconds="${1:-30}"
    local failure_threshold="${2:-3}"
    log_info "Mock circuit breaker operation (timeout: ${timeout_seconds}s, threshold: ${failure_threshold})"
    
    # Simulate circuit breaker with 25% failure rate
    if [[ $((RANDOM % 4)) -eq 0 ]]; then
        log_warning "Mock circuit breaker: operation failed (simulated failure)"
        return 1
    else
        sleep 2
        log_success "Mock circuit breaker: operation succeeded"
        return 0
    fi
}

# Mock retry command execution
execute_retry_command() {
    local attempt_number="${1:-1}"
    local max_attempts="${2:-3}"
    log_info "Mock retry command execution (attempt $attempt_number/$max_attempts)"
    
    # Simulate work
    sleep 1
    
    # Simulate success after 2 attempts for realistic retry testing
    if [[ $attempt_number -ge 2 ]]; then
        log_success "Mock retry command: succeeded after $attempt_number attempts"
        return 0
    else
        log_warning "Mock retry command: failed on attempt $attempt_number"
        return 1
    fi
}

# Mock sequential iteration processing
execute_iteration_iterate_files_sequential() {
    local pattern="${1:-*}"
    log_info "Mock sequential iteration: processing files matching '$pattern'"
    
    # Simulate file processing
    sleep 0.5
    local files=("file1.txt" "file2.txt" "file3.txt")
    
    for file in "${files[@]}"; do
        log_info "Processing file: $file"
        sleep 0.5
    done
    
    log_success "Sequential iteration completed: processed ${#files[@]} files"
    return 0
}

# Mock fallback path execution for testing
execute_fallback_path() {
    local path_id="${1}"
    log_info "Mock fallback path execution: $path_id"
    
    # Simulate work
    sleep 1
    
    # Simulate success for primary_service_call, failure for others to test fallback behavior
    case "$path_id" in
        "primary_service_call")
            log_success "Primary service call succeeded"
            return 0
            ;;
        "secondary_service_call") 
            log_warning "Secondary service call failed"
            return 1
            ;;
        "cache_fallback_call")
            log_warning "Cache fallback failed"
            return 1
            ;;
        "default_response_call")
            log_success "Default response call succeeded"
            return 0
            ;;
        *)
            log_info "Unknown fallback path succeeded: $path_id"
            return 0
            ;;
    esac
}

# Workflow Execution

# Node: initialize_moderation_system
/bin/bash -c "set -euo pipefail
echo \"🛡️ Initializing Content Moderation Pipeline...\"

# Configuration validation
CONTENT=\"\${CONTENT_INPUT}\"
STRICTNESS=\"\${MODERATION_STRICTNESS:-moderate}\"
PROFANITY_CHECK=\"\${ENABLE_PROFANITY_CHECK:-true}\"
SENTIMENT_CHECK=\"\${ENABLE_SENTIMENT_ANALYSIS:-true}\"
WEBHOOK=\"\${WEBHOOK_URL:-}\"

echo \"🔧 Moderation Configuration:\"
echo \"  Content Length: \${#CONTENT} characters\"
echo \"  Strictness Level: \$STRICTNESS\"
echo \"  Profanity Check: \$PROFANITY_CHECK\"
echo \"  Sentiment Analysis: \$SENTIMENT_CHECK\"
echo \"  Webhook Alerts: \$([ -n \"\$WEBHOOK\" ] && echo \"Enabled\" || echo \"Disabled\")\"

# Create moderation workspace
mkdir -p /tmp/content_moderation
mkdir -p /tmp/content_moderation/analysis
mkdir -p /tmp/content_moderation/reports

# Initialize content file
echo \"\$CONTENT\" > /tmp/content_moderation/input_content.txt

# Initialize analysis results
echo '{\"moderation_results\":[],\"flags\":[],\"scores\":{},\"recommendations\":[]}' > /tmp/content_moderation/analysis/results.json

# Set strictness parameters
case \"\$STRICTNESS\" in
  \"lenient\")
    echo '{\"profanity_threshold\":0.8,\"toxicity_threshold\":0.7,\"hate_threshold\":0.8}' > /tmp/content_moderation/thresholds.json
    ;;
  \"moderate\")
    echo '{\"profanity_threshold\":0.6,\"toxicity_threshold\":0.5,\"hate_threshold\":0.6}' > /tmp/content_moderation/thresholds.json
    ;;
  \"strict\")
    echo '{\"profanity_threshold\":0.3,\"toxicity_threshold\":0.3,\"hate_threshold\":0.3}' > /tmp/content_moderation/thresholds.json
    ;;
  *)
    echo '{\"profanity_threshold\":0.6,\"toxicity_threshold\":0.5,\"hate_threshold\":0.6}' > /tmp/content_moderation/thresholds.json
    ;;
esac

echo \"✅ Moderation system initialized successfully\"
"

# Node: basic_content_analysis
/bin/bash -c "set -euo pipefail
echo \"🔍 Performing basic content analysis...\"

CONTENT_FILE=\"/tmp/content_moderation/input_content.txt\"
ANALYSIS_DIR=\"/tmp/content_moderation/analysis\"

# Basic content metrics
CHAR_COUNT=\$(wc -c < \"\$CONTENT_FILE\")
WORD_COUNT=\$(wc -w < \"\$CONTENT_FILE\")
LINE_COUNT=\$(wc -l < \"\$CONTENT_FILE\")

echo \"📊 Content Metrics:\"
echo \"  Characters: \$CHAR_COUNT\"
echo \"  Words: \$WORD_COUNT\" 
echo \"  Lines: \$LINE_COUNT\"

# Basic safety checks
CONTENT=\$(cat \"\$CONTENT_FILE\")

# Check for URLs and links
URL_COUNT=\$(echo \"\$CONTENT\" | grep -oE 'https?://[^[:space:]]+' | wc -l || echo \"0\")

# Check for email addresses
EMAIL_COUNT=\$(echo \"\$CONTENT\" | grep -oE '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}' | wc -l || echo \"0\")

# Check for phone numbers (basic pattern)
PHONE_COUNT=\$(echo \"\$CONTENT\" | grep -oE '[0-9]{3}-[0-9]{3}-[0-9]{4}|\\\\([0-9]{3}\\\\)[[:space:]]*[0-9]{3}-[0-9]{4}' | wc -l || echo \"0\")

echo \"📧 Content Pattern Analysis:\"
echo \"  URLs found: \$URL_COUNT\"
echo \"  Email addresses: \$EMAIL_COUNT\"
echo \"  Phone numbers: \$PHONE_COUNT\"

# Basic content flags
FLAGS=\"\"
if [ \"\$URL_COUNT\" -gt 5 ]; then
  FLAGS=\"\$FLAGS,excessive_links\"
fi
if [ \"\$EMAIL_COUNT\" -gt 3 ]; then
  FLAGS=\"\$FLAGS,excessive_emails\"  
fi
if [ \"\$CHAR_COUNT\" -gt 10000 ]; then
  FLAGS=\"\$FLAGS,very_long_content\"
fi

# Save basic analysis
cat > \"\$ANALYSIS_DIR/basic_analysis.json\" <<EOF
{
  \"metrics\": {
    \"character_count\": \$CHAR_COUNT,
    \"word_count\": \$WORD_COUNT,
    \"line_count\": \$LINE_COUNT,
    \"url_count\": \$URL_COUNT,
    \"email_count\": \$EMAIL_COUNT,
    \"phone_count\": \$PHONE_COUNT
  },
  \"flags\": \"\${FLAGS#,}\",
  \"analysis_timestamp\": \"\$(date -Iseconds)\"
}
EOF

echo \"✅ Basic content analysis complete\"
"

# Node: profanity_detection
/bin/bash -c "set -euo pipefail
echo \"🚫 Running profanity and offensive language detection...\"

ENABLE_CHECK=\"\${ENABLE_PROFANITY_CHECK:-true}\"

if [ \"\$ENABLE_CHECK\" != \"true\" ]; then
  echo \"ℹ️ Profanity check disabled by configuration\"
  echo '{\"profanity_detected\":false,\"score\":0,\"flagged_terms\":[],\"enabled\":false}' > /tmp/content_moderation/analysis/profanity.json
  exit 0
fi

CONTENT_FILE=\"/tmp/content_moderation/input_content.txt\"
CONTENT=\$(cat \"\$CONTENT_FILE\" | tr '[:upper:]' '[:lower:]')

# Basic profanity word list (production would use comprehensive database)
PROFANITY_WORDS=\"damn hell shit fuck ass bitch bastard crap stupid idiot moron dumb\"

# Offensive terms and hate speech indicators
HATE_TERMS=\"hate nazi racist sexist bigot discrimination harassment\"

# Violence and threat indicators  
VIOLENCE_TERMS=\"kill murder die death threat attack harm violence\"

echo \"🔍 Scanning content for inappropriate language...\"

PROFANITY_MATCHES=\"\"
HATE_MATCHES=\"\"
VIOLENCE_MATCHES=\"\"
PROFANITY_SCORE=0
HATE_SCORE=0
VIOLENCE_SCORE=0

# Check profanity
for word in \$PROFANITY_WORDS; do
  if echo \"\$CONTENT\" | grep -qi \"\\\\b\$word\\\\b\"; then
    PROFANITY_MATCHES=\"\$PROFANITY_MATCHES,\$word\"
    PROFANITY_SCORE=\$((PROFANITY_SCORE + 1))
  fi
done

# Check hate speech
for word in \$HATE_TERMS; do
  if echo \"\$CONTENT\" | grep -qi \"\\\\b\$word\\\\b\"; then
    HATE_MATCHES=\"\$HATE_MATCHES,\$word\"
    HATE_SCORE=\$((HATE_SCORE + 2))  # Hate speech weighted higher
  fi
done

# Check violence/threats
for word in \$VIOLENCE_TERMS; do
  if echo \"\$CONTENT\" | grep -qi \"\\\\b\$word\\\\b\"; then
    VIOLENCE_MATCHES=\"\$VIOLENCE_MATCHES,\$word\"
    VIOLENCE_SCORE=\$((VIOLENCE_SCORE + 3))  # Violence weighted highest
  fi
done

TOTAL_SCORE=\$((PROFANITY_SCORE + HATE_SCORE + VIOLENCE_SCORE))
WORD_COUNT=\$(wc -w < \"\$CONTENT_FILE\")
NORMALIZED_SCORE=\$(echo \"scale=2; \$TOTAL_SCORE / \$WORD_COUNT * 100\" | bc -l || echo \"0\")

echo \"📊 Profanity Detection Results:\"
echo \"  Profanity matches: \${PROFANITY_MATCHES#,}\"
echo \"  Hate speech matches: \${HATE_MATCHES#,}\"
echo \"  Violence/threat matches: \${VIOLENCE_MATCHES#,}\"
echo \"  Total flagged terms: \$TOTAL_SCORE\"
echo \"  Normalized score: \${NORMALIZED_SCORE}%\"

# Determine if content is flagged
THRESHOLD=\$(jq -r '.profanity_threshold' /tmp/content_moderation/thresholds.json)
FLAGGED=\$(echo \"\$NORMALIZED_SCORE > \$THRESHOLD * 100\" | bc -l | grep -q \"1\" && echo \"true\" || echo \"false\")

echo \"  Threshold: \${THRESHOLD}%\"
echo \"  Content flagged: \$FLAGGED\"

# Save profanity analysis
cat > /tmp/content_moderation/analysis/profanity.json <<EOF
{
  \"profanity_detected\": \$FLAGGED,
  \"normalized_score\": \$NORMALIZED_SCORE,
  \"raw_score\": \$TOTAL_SCORE,
  \"threshold\": \$THRESHOLD,
  \"flagged_terms\": {
    \"profanity\": \"\${PROFANITY_MATCHES#,}\",
    \"hate_speech\": \"\${HATE_MATCHES#,}\",
    \"violence_threats\": \"\${VIOLENCE_MATCHES#,}\"
  },
  \"enabled\": true,
  \"analysis_timestamp\": \"\$(date -Iseconds)\"
}
EOF

echo \"✅ Profanity detection complete\"
"

# Node: ai_content_analysis
# Function to validate and extract content from API response
extract_llm_content() {
    local response="$1"
    if [[ -n "$response" ]] && echo "$response" | jq -e '.choices[0].message.content' >/dev/null 2>&1; then
        echo "$response" | jq -r '.choices[0].message.content'
        return 0
    else
        return 1
    fi
}

# Three-stage LLM fallback: OpenAI -> LLMv7 -> Demo
llm_response=""
llm_content=""

# Stage 1: Try OpenAI if API key is available
if [[ -n "${OPENAI_API_KEY:-}" ]]; then
    log_info "Using OpenAI API..."
    llm_response=$(curl -s -X POST "https://api.openai.com/v1/chat/completions" \
      -H "Authorization: Bearer $OPENAI_API_KEY" \
      -H "Content-Type: application/json" \
      -d '{"model": "gpt-3.5-turbo", "messages": [{"role": "user", "content": "Hello"}]}' \
      --connect-timeout 30 --max-time 60)
    if extract_llm_content "$llm_response" >/dev/null 2>&1; then
        llm_content=$(extract_llm_content "$llm_response")
        log_info "OpenAI API successful"
    else
        log_warning "OpenAI API failed, trying LLMv7..."
    fi
fi

# Stage 2: Try LLMv7 if OpenAI failed or no key available
if [[ -z "$llm_content" ]]; then
    if [[ -z "${OPENAI_API_KEY:-}" ]]; then
        log_info "OPENAI_API_KEY not set, using LLMv7..."
    fi
    
    llm_response=$(curl -s -X POST "https://api.llm7.io/v1/chat/completions" \
      -H "Content-Type: application/json" \
      -d '{"model": "default", "messages": [{"role": "user", "content": "Hello"}]}' \
      --connect-timeout 30 --max-time 60)
    if extract_llm_content "$llm_response" >/dev/null 2>&1; then
        llm_content=$(extract_llm_content "$llm_response")
        log_info "LLMv7 API successful"
    else
        log_warning "LLMv7 API also failed, using mock response"
    fi
fi

# Stage 3: Final fallback to demo response
if [[ -z "$llm_content" ]]; then
    llm_content="Mock LLM Response: This is a simulated response because all API calls failed. Original prompt was: Hello"
    log_warning "Using mock response as final fallback"
fi

# Store the content in workflow variable for other nodes to reference
set_workflow_var "llm_content" "$llm_content"
set_workflow_var "llm_success" "true"

# Output the final content
echo "$llm_content"

# Node: process_ai_analysis
/bin/bash -c "set -euo pipefail
echo \"🤖 Processing AI analysis results...\"

AI_RESPONSE=\"\${llm_content}\"
ANALYSIS_DIR=\"/tmp/content_moderation/analysis\"

echo \"📋 AI Analysis Response:\"
echo \"\$AI_RESPONSE\"

# Try to extract JSON from AI response (handle potential formatting issues)
echo \"\$AI_RESPONSE\" | jq . > \"\$ANALYSIS_DIR/ai_analysis.json\" 2>/dev/null || {
  echo \"⚠️ AI response not in valid JSON format, creating structured version\"
  cat > \"\$ANALYSIS_DIR/ai_analysis.json\" <<EOF
  {
    \"safety_assessment\": \"caution\",
    \"safety_score\": 0.5,
    \"sentiment\": \"neutral\", 
    \"sentiment_score\": 0.5,
    \"content_type\": \"text_analysis\",
    \"main_topics\": [\"content_moderation\"],
    \"risk_factors\": [\"ai_parsing_error\"],
    \"recommendations\": [\"manual_review_required\"],
    \"confidence\": 0.3,
    \"raw_response\": \"\$AI_RESPONSE\"
  }
EOF
}

echo \"✅ AI analysis processed and saved\"
"

# Node: sentiment_analysis
/bin/bash -c "set -euo pipefail
echo \"😊 Performing sentiment and emotional analysis...\"

ENABLE_SENTIMENT=\"\${ENABLE_SENTIMENT_ANALYSIS:-true}\"

if [ \"\$ENABLE_SENTIMENT\" != \"true\" ]; then
  echo \"ℹ️ Sentiment analysis disabled by configuration\"
  echo '{\"sentiment_enabled\":false,\"sentiment\":\"neutral\",\"score\":0.5}' > /tmp/content_moderation/analysis/sentiment.json
  exit 0
fi

CONTENT_FILE=\"/tmp/content_moderation/input_content.txt\"
CONTENT=\$(cat \"\$CONTENT_FILE\" | tr '[:upper:]' '[:lower:]')

# Positive sentiment words
POSITIVE_WORDS=\"good great excellent amazing wonderful fantastic brilliant perfect love like enjoy happy pleased satisfied\"

# Negative sentiment words  
NEGATIVE_WORDS=\"bad terrible awful horrible disgusting hate dislike angry frustrated disappointed upset sad\"

# Neutral/professional words
NEUTRAL_WORDS=\"information update notice regarding concerning about per according standard normal\"

echo \"🔍 Analyzing emotional sentiment...\"

POSITIVE_COUNT=0
NEGATIVE_COUNT=0
NEUTRAL_COUNT=0

# Count sentiment indicators
for word in \$POSITIVE_WORDS; do
  COUNT=\$(echo \"\$CONTENT\" | grep -oi \"\\\\b\$word\\\\b\" | wc -l || echo \"0\")
  POSITIVE_COUNT=\$((POSITIVE_COUNT + COUNT))
done

for word in \$NEGATIVE_WORDS; do
  COUNT=\$(echo \"\$CONTENT\" | grep -oi \"\\\\b\$word\\\\b\" | wc -l || echo \"0\")
  NEGATIVE_COUNT=\$((NEGATIVE_COUNT + COUNT))
done

for word in \$NEUTRAL_WORDS; do
  COUNT=\$(echo \"\$CONTENT\" | grep -oi \"\\\\b\$word\\\\b\" | wc -l || echo \"0\")
  NEUTRAL_COUNT=\$((NEUTRAL_COUNT + COUNT))
done

TOTAL_SENTIMENT=\$((POSITIVE_COUNT + NEGATIVE_COUNT + NEUTRAL_COUNT))

# Calculate sentiment scores
if [ \"\$TOTAL_SENTIMENT\" -gt 0 ]; then
  POSITIVE_RATIO=\$(echo \"scale=2; \$POSITIVE_COUNT / \$TOTAL_SENTIMENT\" | bc -l)
  NEGATIVE_RATIO=\$(echo \"scale=2; \$NEGATIVE_COUNT / \$TOTAL_SENTIMENT\" | bc -l)
  NEUTRAL_RATIO=\$(echo \"scale=2; \$NEUTRAL_COUNT / \$TOTAL_SENTIMENT\" | bc -l)
else
  POSITIVE_RATIO=\"0.33\"
  NEGATIVE_RATIO=\"0.33\" 
  NEUTRAL_RATIO=\"0.34\"
fi

# Determine overall sentiment
if (( \$(echo \"\$POSITIVE_RATIO > 0.5\" | bc -l) )); then
  OVERALL_SENTIMENT=\"positive\"
  SENTIMENT_SCORE=\"\$POSITIVE_RATIO\"
elif (( \$(echo \"\$NEGATIVE_RATIO > 0.4\" | bc -l) )); then
  OVERALL_SENTIMENT=\"negative\"
  SENTIMENT_SCORE=\$(echo \"1 - \$NEGATIVE_RATIO\" | bc -l)  # Invert negative for 0-1 scale
else
  OVERALL_SENTIMENT=\"neutral\"
  SENTIMENT_SCORE=\"0.5\"
fi

echo \"📊 Sentiment Analysis Results:\"
echo \"  Positive indicators: \$POSITIVE_COUNT (\$POSITIVE_RATIO)\"
echo \"  Negative indicators: \$NEGATIVE_COUNT (\$NEGATIVE_RATIO)\" 
echo \"  Neutral indicators: \$NEUTRAL_COUNT (\$NEUTRAL_RATIO)\"
echo \"  Overall sentiment: \$OVERALL_SENTIMENT\"
echo \"  Sentiment score: \$SENTIMENT_SCORE\"

# Save sentiment analysis
cat > /tmp/content_moderation/analysis/sentiment.json <<EOF
{
  \"sentiment_enabled\": true,
  \"overall_sentiment\": \"\$OVERALL_SENTIMENT\",
