# Node: compile_moderation_report
/bin/bash -c "set -euo pipefail
echo \"📊 Compiling comprehensive moderation report...\"

ANALYSIS_DIR=\"/tmp/content_moderation/analysis\"
REPORTS_DIR=\"/tmp/content_moderation/reports\"

# Load all analysis results
BASIC_ANALYSIS=\$(cat \"\$ANALYSIS_DIR/basic_analysis.json\" 2>/dev/null || echo '{}')
PROFANITY_ANALYSIS=\$(cat \"\$ANALYSIS_DIR/profanity.json\" 2>/dev/null || echo '{}')
AI_ANALYSIS=\$(cat \"\$ANALYSIS_DIR/ai_analysis.json\" 2>/dev/null || echo '{}')
SENTIMENT_ANALYSIS=\$(cat \"\$ANALYSIS_DIR/sentiment.json\" 2>/dev/null || echo '{}')

echo \"🔍 Analysis Results Summary:\"
echo \"  Basic Analysis: \$(echo \"\$BASIC_ANALYSIS\" | jq -r '.metrics.word_count // \"N/A\"') words\"
echo \"  Profanity Check: \$(echo \"\$PROFANITY_ANALYSIS\" | jq -r '.profanity_detected // \"N/A\"')\"
echo \"  AI Safety Assessment: \$(echo \"\$AI_ANALYSIS\" | jq -r '.safety_assessment // \"N/A\"')\"
echo \"  Sentiment: \$(echo \"\$SENTIMENT_ANALYSIS\" | jq -r '.overall_sentiment // \"N/A\"')\"

# Calculate overall risk score
PROFANITY_FLAGGED=\$(echo \"\$PROFANITY_ANALYSIS\" | jq -r '.profanity_detected // false')
AI_SAFETY_SCORE=\$(echo \"\$AI_ANALYSIS\" | jq -r '.safety_score // 0.5')
AI_SAFETY_ASSESSMENT=\$(echo \"\$AI_ANALYSIS\" | jq -r '.safety_assessment // \"caution\"')

# Determine overall moderation decision
OVERALL_DECISION=\"approved\"
RISK_LEVEL=\"low\"
REQUIRES_REVIEW=false

if [ \"\$PROFANITY_FLAGGED\" = \"true\" ]; then
  OVERALL_DECISION=\"flagged\"
  RISK_LEVEL=\"high\"
  REQUIRES_REVIEW=true
elif [ \"\$AI_SAFETY_ASSESSMENT\" = \"unsafe\" ]; then
  OVERALL_DECISION=\"rejected\"
  RISK_LEVEL=\"critical\"
  REQUIRES_REVIEW=true
elif [ \"\$AI_SAFETY_ASSESSMENT\" = \"caution\" ]; then
  OVERALL_DECISION=\"review_required\"
  RISK_LEVEL=\"medium\"
  REQUIRES_REVIEW=true
fi

# Get recommendations from AI analysis
AI_RECOMMENDATIONS=\$(echo \"\$AI_ANALYSIS\" | jq -r '.recommendations // []' | jq -r '.[]' | tr '\\n' ',' | sed 's/,\$//')

echo \"🎯 Moderation Decision:\"
echo \"  Overall Decision: \$OVERALL_DECISION\"
echo \"  Risk Level: \$RISK_LEVEL\"
echo \"  Requires Manual Review: \$REQUIRES_REVIEW\"

# Create comprehensive report
REPORT_FILE=\"\$REPORTS_DIR/moderation_report_\$(date +%Y%m%d_%H%M%S).json\"

cat > \"\$REPORT_FILE\" <<EOF
{
  \"content_analysis\": {
    \"content_length\": \$(echo \"\$BASIC_ANALYSIS\" | jq -r '.metrics.character_count // 0'),
    \"word_count\": \$(echo \"\$BASIC_ANALYSIS\" | jq -r '.metrics.word_count // 0'),
    \"url_count\": \$(echo \"\$BASIC_ANALYSIS\" | jq -r '.metrics.url_count // 0'),
    \"email_count\": \$(echo \"\$BASIC_ANALYSIS\" | jq -r '.metrics.email_count // 0')
  },
  \"safety_analysis\": {
    \"profanity_detected\": \$PROFANITY_FLAGGED,
    \"profanity_score\": \$(echo \"\$PROFANITY_ANALYSIS\" | jq -r '.normalized_score // 0'),
    \"ai_safety_assessment\": \"\$AI_SAFETY_ASSESSMENT\",
    \"ai_safety_score\": \$AI_SAFETY_SCORE,
    \"sentiment\": \"\$(echo \"\$SENTIMENT_ANALYSIS\" | jq -r '.overall_sentiment // \"neutral\"')\",
    \"sentiment_score\": \$(echo \"\$SENTIMENT_ANALYSIS\" | jq -r '.sentiment_score // 0.5')
  },
  \"moderation_decision\": {
    \"overall_decision\": \"\$OVERALL_DECISION\",
    \"risk_level\": \"\$RISK_LEVEL\", 
    \"requires_manual_review\": \$REQUIRES_REVIEW,
    \"confidence_score\": \$(echo \"\$AI_ANALYSIS\" | jq -r '.confidence // 0.5')
  },
  \"recommendations\": \"\$AI_RECOMMENDATIONS\",
  \"analysis_timestamp\": \"\$(date -Iseconds)\",
  \"moderation_config\": {
    \"strictness\": \"\${MODERATION_STRICTNESS:-moderate}\",
    \"profanity_enabled\": \${ENABLE_PROFANITY_CHECK:-true},
    \"sentiment_enabled\": \${ENABLE_SENTIMENT_ANALYSIS:-true}
  }
}
EOF

# Save report path for later use
echo \"\$REPORT_FILE\" > /tmp/content_moderation/final_report_path.txt

echo \"📋 Comprehensive moderation report saved: \$REPORT_FILE\"
echo \"✅ Moderation analysis complete\"
"

# Node: send_webhook_notification
/bin/bash -c "set -euo pipefail
echo \"📡 Sending webhook notification...\"

WEBHOOK_URL=\"\${WEBHOOK_URL:-}\"

if [ -z \"\$WEBHOOK_URL\" ]; then
  echo \"ℹ️ No webhook URL configured - skipping notification\"
  echo '{\"webhook_sent\":false,\"reason\":\"no_webhook_configured\"}' > /tmp/content_moderation/webhook_result.json
  exit 0
fi

REPORT_FILE=\$(cat /tmp/content_moderation/final_report_path.txt)
MODERATION_RESULT=\$(cat \"\$REPORT_FILE\")

echo \"🚀 Sending notification to: \$WEBHOOK_URL\"

# Send webhook with moderation results
WEBHOOK_RESPONSE=\$(curl -s -X POST \"\$WEBHOOK_URL\" \\
  -H \"Content-Type: application/json\" \\
  -H \"X-Webhook-Type: content-moderation\" \\
  -d \"\$MODERATION_RESULT\" \\
  -w \"HTTP_CODE:%{http_code}\" || echo \"HTTP_CODE:000\")

HTTP_CODE=\$(echo \"\$WEBHOOK_RESPONSE\" | grep -o \"HTTP_CODE:[0-9]*\" | cut -d: -f2)
RESPONSE_BODY=\$(echo \"\$WEBHOOK_RESPONSE\" | sed 's/HTTP_CODE:[0-9]*\$//')

if [ \"\$HTTP_CODE\" -ge 200 ] && [ \"\$HTTP_CODE\" -lt 300 ]; then
  echo \"✅ Webhook notification sent successfully (HTTP \$HTTP_CODE)\"
  WEBHOOK_SUCCESS=true
else
  echo \"❌ Webhook notification failed (HTTP \$HTTP_CODE)\"
  echo \"Response: \$RESPONSE_BODY\"
  WEBHOOK_SUCCESS=false
fi

# Save webhook result
cat > /tmp/content_moderation/webhook_result.json <<EOF
{
  \"webhook_sent\": \$WEBHOOK_SUCCESS,
  \"webhook_url\": \"\$WEBHOOK_URL\",
  \"http_code\": \$HTTP_CODE,
  \"response\": \"\$RESPONSE_BODY\",
  \"timestamp\": \"\$(date -Iseconds)\"
}
EOF

echo \"📬 Webhook notification process complete\"
"

# Node: generate_final_summary

# Node: generate_final_summary (Generate Moderation Summary)
execute_template_transform_generate_final_summary() {
    log_step "🔧 Template Transform: Generate Moderation Summary"

    local output_var="moderation_summary"
    local template_content=""

    # Inline template content
    template_content=''
    log_debug "Using inline template content"

    # Validate template was resolved
    if [[ -z "$template_content" ]]; then
        log_error "Failed to resolve template content"
        set_workflow_var "$output_var" ""
        return 1
    fi

    log_debug "Template resolved, length: ${#template_content} characters"

    # Apply template parameters (basic substitution)
    local rendered_content="$template_content"

    # No template parameters configured
    log_debug "No template parameters to process"

    # Advanced template functions processing
    rendered_content=$(process_template_functions "$rendered_content")
    
    # Additional variable substitution for workflow variables
    rendered_content=$(substitute_variables "$rendered_content")

    # Set output variable
    set_workflow_var "$output_var" "$rendered_content"

    log_success "Template transformed and stored in $output_var"
    log_debug "Template output length: ${#rendered_content} characters"
}

# Advanced template function processor for node generate_final_summary
process_template_functions_generate_final_summary() {
    local content="$1"

    # {{#date}} -> current date (YYYY-MM-DD)
    content="${content//\{\{#date\}\}/$(date '+%Y-%m-%d')}"

    # {{#time}} -> current time (HH:MM:SS)
    content="${content//\{\{#time\}\}/$(date '+%H:%M:%S')}"

    # {{#datetime}} -> current date and time (ISO 8601)
    content="${content//\{\{#datetime\}\}/$(date -Iseconds)}"

    # {{#timestamp}} -> current Unix timestamp
    content="${content//\{\{#timestamp\}\}/$(date '+%s')}"

    # {{#uuid}} -> generate UUID (fallback if uuidgen not available)
    if command -v uuidgen >/dev/null 2>&1; then
        content="${content//\{\{#uuid\}\}/$(uuidgen)}"
    else
        # Fallback UUID generation using date and random
        local fallback_uuid="uuid-$(date +%s)-$RANDOM"
        content="${content//\{\{#uuid\}\}/$fallback_uuid}"
    fi

    # {{#random}} -> random number (0-32767)
    content="${content//\{\{#random\}\}/$RANDOM}"

    # {{#hostname}} -> current hostname
    content="${content//\{\{#hostname\}\}/$(hostname 2>/dev/null || echo 'unknown')}"

    # {{#user}} -> current user
    content="${content//\{\{#user\}\}/$(whoami 2>/dev/null || echo 'unknown')}"

    # {{#pwd}} -> current working directory
    content="${content//\{\{#pwd\}\}/$(pwd)}"

    # Process variable-based functions with regex matching
    # {{#base64:variable}} -> base64 encode variable
    while [[ "$content" =~ \{\{#base64:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            if command -v base64 >/dev/null 2>&1; then
                encoded_value="$(echo -n "$var_value" | base64 -w 0)"
            else
                log_warning "base64 command not available, skipping encoding for $var_name"
                encoded_value="$var_value"
            fi
        fi
        
        content="${content//\{\{#base64:$var_name\}\}/$encoded_value}"
    done

    # {{#url_encode:variable}} -> URL encode variable
    while [[ "$content" =~ \{\{#url_encode:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            # Simple URL encoding (encode spaces and special characters)
            encoded_value="$(echo "$var_value" | sed 's/ /%20/g; s/&/%26/g; s/?/%3F/g; s/=/%3D/g')"
        fi
        
        content="${content//\{\{#url_encode:$var_name\}\}/$encoded_value}"
    done

    # {{#upper:variable}} -> uppercase variable
    while [[ "$content" =~ \{\{#upper:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local upper_value=""
        
        if [[ -n "$var_value" ]]; then
            upper_value="$(echo "$var_value" | tr '[:lower:]' '[:upper:]')"
        fi
        
        content="${content//\{\{#upper:$var_name\}\}/$upper_value}"
    done

    # {{#lower:variable}} -> lowercase variable
    while [[ "$content" =~ \{\{#lower:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local lower_value=""
        
        if [[ -n "$var_value" ]]; then
            lower_value="$(echo "$var_value" | tr '[:upper:]' '[:lower:]')"
        fi
        
        content="${content//\{\{#lower:$var_name\}\}/$lower_value}"
    done

    # {{#length:variable}} -> length of variable
    while [[ "$content" =~ \{\{#length:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local length_value="${#var_value}"
        
        content="${content//\{\{#length:$var_name\}\}/$length_value}"
    done

    # {{#json_escape:variable}} -> JSON escape variable
    while [[ "$content" =~ \{\{#json_escape:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local escaped_value=""
        
        if [[ -n "$var_value" ]]; then
            # Basic JSON escaping
            escaped_value="$(echo "$var_value" | sed 's/\\/\\\\/g; s/"/\\"/g; s/\t/\\t/g; s/\n/\\n/g; s/\r/\\r/g')"
        fi
        
        content="${content//\{\{#json_escape:$var_name\}\}/$escaped_value}"
    done

    echo "$content"
}

# Use the node-specific template function processor
process_template_functions() {
    process_template_functions_generate_final_summary "$1"
}
execute_template_transform_generate_final_summary

